const inactiveDepartmentLeaders = `-- name: InactiveDepartmentLeaders :many
SELECT d.id, d.code, u.full_name, (d.head_user_id = u.id)::boolean AS is_head
  FROM departments d JOIN users u ON u.tenant_id = d.tenant_id AND (u.id = d.head_user_id OR u.id = d.deputy_user_id)
 WHERE d.tenant_id = $1 AND d.property_id = $2 AND NOT u.is_active
 ORDER BY d.code, u.id
`

type InactiveDepartmentLeadersParams struct {
	TenantID   int64
	PropertyID int64
}

type InactiveDepartmentLeadersRow struct {
	ID       int64
	Code     string
	FullName string
	IsHead   bool
}

// The setup check of the chain: a head or a deputy who is not active any more, with the department.
func (q *Queries) InactiveDepartmentLeaders(ctx context.Context, arg InactiveDepartmentLeadersParams) ([]InactiveDepartmentLeadersRow, error) {
	rows, err := q.db.Query(ctx, inactiveDepartmentLeaders, arg.TenantID, arg.PropertyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []InactiveDepartmentLeadersRow{}
	for rows.Next() {
		var i InactiveDepartmentLeadersRow
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.FullName,
			&i.IsHead,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

